-- Older adult strength, mobility and longevity programs (GRIZZ, 2026-10-20).
-- Three 24-week programs for adults 60+ (or deconditioned 50+ after
-- assessment), each in three 8-week blocks. Week 8 of each block is the
-- reassess week. Generated from a script, so every row is written out.
-- New library exercises (no video yet, the app shows a watch-online link).
insert into public.exercises (name, category, source, external_url, sort_order, home_friendly)
select v.name, v.category, 'own_library', null, 0, v.home
from (values
  ('Chair Sit-to-Stand', 'Legs', true),
  ('Wall Push-Up', 'Push', true),
  ('Supported Calf Raise', 'Calves', true),
  ('Supported Tandem Stance', 'Core', true),
  ('Supported Single-Leg Balance', 'Core', true),
  ('Supported Tandem Walk', 'Core', true),
  ('Supported Multidirectional Stepping', 'Core', true),
  ('Suitcase Carry', 'Forearms & Grip', true),
  ('Dumbbell Farmer''s Carry', 'Forearms & Grip', true),
  ('Goblet Box Squat', 'Legs', true),
  ('Quick-Rise Box Squat', 'Legs', true),
  ('Dumbbell Romanian Deadlift', 'Posterior Chain', true),
  ('Supported Split Squat', 'Legs', true),
  ('Supported Reverse Lunge', 'Legs', true)
) as v(name, category, home)
where not exists (select 1 from public.exercises e where e.name = v.name);

do $$
declare
