begin
  if exists (select 1 from public.programs where trainer_id is null and name = 'Older Adult 1 - Beginner Foundation') then
    return;
  end if;
  insert into public.programs (trainer_id, name, kind, place, weeks, description, nutrition, warm_up, day_titles)
  values (null, 'Older Adult 1 - Beginner Foundation', 'weekly', 'gym', 24, 'For adults 60+ (or 50+ after an assessment) who are new to exercise or coming back after a long break. Months 1-6: build confidence, mobility, basic strength and walking. Three 8-week blocks: weeks 1-8 learn the movements (2 strength days), weeks 9-16 build basic strength and walking, weeks 17-24 add functional strength (3 strength days when you recover well). Every 8th week is lighter and your coach re-tests you. Rules for every session: warm up for 5-8 minutes, move with control before adding weight, breathe out as you lift or push and never hold your breath, use a support for balance work, and no forced stretching or loaded twisting. Mild, familiar discomfort can be fine, but stop and tell your coach if you feel sharp pain, swelling, the joint giving way or pain that gets worse. Stop straight away and get medical help for chest pain, feeling faint, unusual breathlessness or new numbness, weakness or trouble speaking.', 'Have protein at every meal (eggs, fish, chicken, beans, yoghurt or milk), about 1-1.2 g per kg of body weight a day unless your doctor says otherwise, to keep your muscle. Calcium and vitamin D help keep bones strong. Drink water through the day, since thirst gets weaker with age, and a little more on training days.', '5-8 minutes: easy walk or bike, then holding a support: march on the spot for 30 seconds, 10 arm circles each way, 5 sit-to-stands from a chair and 5 slow cat-cows. Breathe out as you lift or push.',
    array['Full-body strength A','Easy walk and mobility','Rest or gentle activity','Full-body strength B','Easy walk and balance','Optional gentle walk','Recovery','Full-body strength A','Easy walk and mobility','Rest or gentle activity','Full-body strength B','Easy walk and balance','Optional gentle walk','Recovery','Full-body strength A','Easy walk and mobility','Rest or gentle activity','Full-body strength B','Easy walk and balance','Optional gentle walk','Recovery','Full-body strength A','Easy walk and mobility','Rest or gentle activity','Full-body strength B','Easy walk and balance','Optional gentle walk','Recovery','Full-body strength A','Easy walk and mobility','Rest or gentle activity','Full-body strength B','Easy walk and balance','Optional gentle walk','Recovery','Full-body strength A','Easy walk and mobility','Rest or gentle activity','Full-body strength B','Easy walk and balance','Optional gentle walk','Recovery','Full-body strength A','Easy walk and mobility','Rest or gentle activity','Full-body strength B','Easy walk and balance','Optional gentle walk','Recovery','Full-body strength A (reassess week)','Easy walk and mobility','Rest or gentle activity','Full-body strength B','Easy walk and balance','Optional gentle walk','Recovery','Full-body strength A','Walk and mobility','Rest or gentle activity','Full-body strength B','Walk and balance','Gentle walk','Recovery','Full-body strength A','Walk and mobility','Rest or gentle activity','Full-body strength B','Walk and balance','Gentle walk','Recovery','Full-body strength A','Walk and mobility','Rest or gentle activity','Full-body strength B','Walk and balance','Gentle walk','Recovery','Full-body strength A','Walk and mobility','Rest or gentle activity','Full-body strength B','Walk and balance','Gentle walk','Recovery','Full-body strength A','Walk and mobility','Rest or gentle activity','Full-body strength B','Walk and balance','Gentle walk','Recovery','Full-body strength A','Walk and mobility','Rest or ge