do $$
declare
  prog uuid;
begin
  if exists (select 1 from public.programs where trainer_id is null and name = 'Older Adult 2 - Strength & Stability') then
    return;
  end if;
  insert into public.programs (trainer_id, name, kind, place, weeks, description, nutrition, warm_up, day_titles)
  values (null, 'Older Adult 2 - Strength & Stability', 'weekly', 'gym', 24, 'For adults 60+ who finished the beginner program or already move well and exercise regularly. Months 7-12: more strength, stability, joint resilience and fitness. 3 strength days a week at an effort of about 5-7 out of 10, cardio on 2-3 days and a recovery and mobility day. Every 8th week is lighter and your coach re-tests you. Rules for every session: warm up for 5-8 minutes, move with control before adding weight, breathe out as you lift or push and never hold your breath, use a support for balance work, and no forced stretching or loaded twisting. Mild, familiar discomfort can be fine, but stop and tell your coach if you feel sharp pain, swelling, the joint giving way or pain that gets worse. Stop straight away and get medical help for chest pain, feeling faint, unusual breathlessness or new numbness, weakness or trouble speaking.', 'Have protein at every meal (eggs, fish, chicken, beans, yoghurt or milk), about 1-1.2 g per kg of body weight a day unless your doctor says otherwise, to keep your muscle. Calcium and vitamin D help keep bones strong. Drink water through the day, since thirst gets weaker with age, and a little more on training days.', '5-8 minutes: easy walk or bike, then holding a support: march on the spot for 30 seconds, 10 arm circles each way, 5 sit-to-stands from a chair and 5 slow cat-cows. Breathe out as you lift or push.',
    array['Strength A','Cardio','Strength B','Recovery and mobility','Strength C','Cardio and balance','Rest','Strength A','Cardio','Strength B','Recovery and mobility','Strength C','Cardio and balance','Rest','Strength A','Cardio','Strength B','Recovery and mobility','Strength C','Cardio and balance','Rest','Strength A','Cardio','Strength B','Recovery and mobility','Strength C','Cardio and balance','Rest','Strength A','Cardio','Strength B','Recovery and mobility','Strength C','Cardio and balance','Rest','Strength A','Cardio','Strength B','Recovery and mobility','Strength C','Cardio and balance','Rest','Strength A','Cardio','Strength B','Recovery and mobility','Strength C','Cardio and balance','Rest','Strength A (reassess week)','Cardio','Strength B','Recovery and mobility','Strength C','Cardio and balance','Rest','Strength A','Cardio','Strength B','Recovery and mobility','Strength C','Cardio and balance','Rest','Strength A','Cardio','Strength B','Recovery and mobility','Strength C','Cardio and balance','Rest','Strength A','Cardio','Strength B','Recovery and mobility','Strength C','Cardio and balance','Rest','Strength A','Cardio','Strength B','Recovery and mobility','Strength C','Cardio and balance','Rest','Strength A','Cardio','Strength B','Recovery and mobility','Strength C','Cardio and balance','Rest','Strength A','Cardio','Strength B','Recovery and mobility','Strength C','Cardio and balance','Rest','Strength A','Cardio','Strength B','Recovery and mobility','Strength C','Cardio and balance','Rest','Strength A (reassess week)','Cardio','Strength B','Recovery and mobility','Strength C','Cardio and balance','Rest','Strength A','Cardio','Strength B','Recovery and mobility','Strength C','Cardio and balance','Rest','Strength A','Cardio','Strength B','Recovery and mobility','Strength C','Cardio and balance','Rest','Strength A','Cardio','Strength B','Recovery and mobility','Strength C','Cardio and balance','Rest','Strength A','Cardio','Strength B','Recovery and mobility'