declare
  prog uuid;
begin
  if exists (select 1 from public.programs where trainer_id is null and name = 'Older Adult 3 - Functional Strength & Independence') then
    return;
  end if;
  insert into public.programs (trainer_id, name, kind, place, weeks, description, nutrition, warm_up, day_titles)
  values (null, 'Older Adult 3 - Functional Strength & Independence', 'weekly', 'gym', 24, 'For adults 60+ with good basic strength and exercise experience. Months 13-18: stay independent, strong and steady, with safe, quicker movement (stand up quickly, lower slowly) and balance stepping in every direction. The goal is getting out of chairs, climbing stairs, carrying shopping and walking comfortably, not lifting the heaviest weights. Every 8th week is lighter and your coach re-tests you. Rules for every session: warm up for 5-8 minutes, move with control before adding weight, breathe out as you lift or push and never hold your breath, use a support for balance work, and no forced stretching or loaded twisting. Mild, familiar discomfort can be fine, but stop and tell your coach if you feel sharp pain, swelling, the joint giving way or pain that gets worse. Stop straight away and get medical help for chest pain, feeling faint, unusual breathlessness or new numbness, weakness or trouble speaking.', 'Have protein at every meal (eggs, fish, chicken, beans, yoghurt or milk), about 1-1.2 g per kg of body weight a day unless your doctor says otherwise, to keep your muscle. Calcium and vitamin D help keep bones strong. Drink water through the day, since thirst gets weaker with age, and a little more on training days.', '5-8 minutes: easy walk or bike, then holding a support: march on the spot for 30 seconds, 10 arm circles each way, 5 sit-to-stands from a chair and 5 slow cat-cows. Breathe out as you lift or push.',
    array['Lower body and core','Cardio and balance','Upper body and core','Recovery or mobility','Full-body functional strength','Cardio and balance','Rest','Lower body and core','Cardio and balance','Upper body and core','Recovery or mobility','Full-body functional strength','Cardio and balance','Rest','Lower body and core','Cardio and balance','Upper body and core','Recovery or mobility','Full-body functional strength','Cardio and balance','Rest','Lower body and core','Cardio and balance','Upper body and core','Recovery or mobility','Full-body functional strength','Cardio and balance','Rest','Lower body and core','Cardio and balance','Upper body and core','Recovery or mobility','Full-body functional strength','Cardio and balance','Rest','Lower body and core','Cardio and balance','Upper body and core','Recovery or mobility','Full-body functional strength','Cardio and balance','Rest','Lower body and core','Cardio and balance','Upper body and core','Recovery or mobility','Full-body functional strength','Cardio and balance','Rest','Lower body and core (reassess week)','Cardio and balance','Upper body and core','Recovery or mobility','Full-body functional strength','Cardio and balance','Rest','Lower body and core','Cardio and balance','Upper body and core','Recovery or mobility','Full-body functional strength','Cardio and balance','Rest','Lower body and core','Cardio and balance','Upper body and core','Recovery or mobility','Full-body functional strength','Cardio and balance','Rest','Lower body and core','Cardio and balance','Upper body and core','Recovery or mobility','Full-body functional strength','Cardio and balance','Rest','Lower body and core','Cardio and balance','Upper body and core','Recovery or mobility','Full-body functional strength','Cardio and balance','Rest','Lower body and core','Cardio and balance','Upper body and core','Recovery or mobility','Full-body functional strength','Cardio and balance','Rest','Lower body and core','Cardio and balance','Upper 